{"explanation":"Start with a square and shade half of it. Then shade half of what remains, and repeat: the new pieces have areas 1/2, 1/4, 1/8, and so on. The unshaded region keeps shrinking toward zero, so the shaded fractions add up to the whole square: 1.","manimCode":"const title = new Text({ text: 'Fill the square, half of the remainder at a time', color: WHITE, fontSize: 32 });
title.moveTo([0, 3.25, 0]);
const equation = new Text({ text: '1/2 + 1/4 + 1/8 + ... = 1', color: YELLOW, fontSize: 32 });
equation.moveTo([0, -3.2, 0]);
const border = new Polygon({ vertices: [[-2, -1.85, 0], [2, -1.85, 0], [2, 2.15, 0], [-2, 2.15, 0]], color: WHITE });
border.setFillOpacity(0).setStrokeWidth(3);
scene.add(title, equation);
await scene.play(new Create(border));

const colors = [BLUE, TEAL, GREEN, YELLOW, ORANGE, RED, PURPLE, BLUE_C, GREEN_C, GOLD];
const pieces = [];
const labels = [];
let left = -2, right = 2, bottom = -1.85, top = 2.15;
for (let i = 0; i < 10; i++) {
  let x1, x2, y1, y2;
  if (i % 2 === 0) {
    const mid = (left + right) / 2;
    x1 = left; x2 = mid; y1 = bottom; y2 = top;
    left = mid;
  } else {
    const mid = (bottom + top) / 2;
    x1 = left; x2 = right; y1 = mid; y2 = top;
    top = mid;
  }
  const piece = new Polygon({ vertices: [[x1, y1, 0], [x2, y1, 0], [x2, y2, 0], [x1, y2, 0]], color: colors[i] });
  piece.setFill(colors[i], 0.88).setStrokeWidth(2);
  pieces.push(piece);
  if (i < 4) {
    const label = new Text({ text: `1/${2 ** (i + 1)}`, color: WHITE, fontSize: i < 2 ? 27 : 22 });
    label.moveTo([(x1 + x2) / 2, (y1 + y2) / 2, 0]);
    labels.push(label);
  }
}

let visible = 0;
for (let i = 0; i < 5; i++) {
  await scene.play(new FadeIn(pieces[i]));
  if (i < labels.length) scene.add(labels[i]);
  visible++;
}
scene.remove(border);
scene.add(border);

function showCount(count) {
  for (let i = 0; i < visible; i++) scene.remove(pieces[i]);
  for (let i = 0; i < Math.min(visible, labels.length); i++) scene.remove(labels[i]);
  visible = count;
  for (let i = 0; i < visible; i++) scene.add(pieces[i]);
  for (let i = 0; i < Math.min(visible, labels.length); i++) scene.add(labels[i]);
  scene.remove(border);
  scene.add(border);
}

const controls = new Controls(scene, { position: 'top-right' });
controls.addSlider({ label: 'Pieces shaded', min: 0, max: 10, value: 5, step: 1, onChange: (value) => showCount(Math.round(value)) });
await scene.wait(999999);"}

